using System;using System.Linq;using System.IO;using System.Collections.Generic;
namespace Ara {public static class Adherence {
 static string S(Dictionary<string,object> d,string k){return JsonMap.Str(d,k);}static int N(Dictionary<string,object>d,string k){object v;return d.TryGetValue(k,out v)?Convert.ToInt32(v):0;}
 static bool Eligible(Dictionary<string,object>b){return !new[]{"기상","끼니 준비","수면","수면 예상"}.Contains(S(b,"category"))&&S(b,"prep_for")=="";}
 static Dictionary<string,object> Flat(Day d,CellBlock b){return JsonMap.Obj("id",b.Id,"category",b.Category,"name",b.Name??"","meal_id",b.MealId??"","template_id",b.TemplateId??"","prep_for",b.PrepFor??"","start",(int)(b.Start-PhoneCodec.Date(d.Date)).TotalMinutes,"end",(int)(b.End-PhoneCodec.Date(d.Date)).TotalMinutes);}
 static bool Compatible(Dictionary<string,object>a,Dictionary<string,object>b){return S(a,"category")==S(b,"category")&&(S(a,"meal_id").Length>0?S(a,"meal_id")==S(b,"meal_id"):S(b,"meal_id")=="")&&(S(a,"template_id")==""||S(b,"template_id")==""||S(a,"template_id")==S(b,"template_id"));}
 static bool SameAction(Dictionary<string,object>a,Dictionary<string,object>b){return S(a,"category")==S(b,"category")&&(S(a,"meal_id")==""||S(b,"meal_id")==""||S(a,"meal_id")==S(b,"meal_id"))&&(S(a,"template_id")==""||S(b,"template_id")==""||S(a,"template_id")==S(b,"template_id"))&&(new[]{"식사","존2","웨이트"}.Contains(S(a,"category"))||S(a,"meal_id")!=""&&S(b,"meal_id")!=""?S(a,"meal_id")==S(b,"meal_id")||S(a,"meal_id")==""||S(b,"meal_id")=="":S(a,"name")==S(b,"name"));}
 static List<Dictionary<string,object>> Groups(Day d){var result=new List<Dictionary<string,object>>();foreach(var block in d.Records.Where(b=>b.Start>=d.Wake).OrderBy(b=>b.Start)){var b=Flat(d,block);var last=result.LastOrDefault();if(last!=null&&N(last,"end")==N(b,"start")&&SameAction(last,b)){last["end"]=b["end"];last["ids"]=JsonMap.Items(last,"ids").Concat(new object[]{b["id"]}).ToArray();if(S(last,"meal_id")=="")last["meal_id"]=b["meal_id"];if(S(last,"template_id")=="")last["template_id"]=b["template_id"];}else{b["ids"]=new object[]{b["id"]};result.Add(b);}}return result.Where(Eligible).ToList();}
 public static Dictionary<string,object> Read(Day d){return string.IsNullOrEmpty(d.AdherenceState)?null:JsonMap.Read(d.AdherenceState);}
 public static void Update(State before,Day old,State s,Day d,List<CellBlock> previous){SharedEngine.Run("adherenceUpdate",s,d,JsonMap.Obj("before",SharedEngine.DayState(before,old),"previous",SharedEngine.Json(previous)));}
 public static Dictionary<string,object> Report(Day d){return JsonMap.Child(SharedEngine.DayCall("report",d),"value");}
 public static decimal? Score(Day d){var report=Report(d);return report["score"]==null?(decimal?)null:Convert.ToDecimal(report["score"]);}
 public static void Reconcile(Day d,Day[] sources){var data=Read(d);if(data==null)return;var links=JsonMap.Child(data,"links");var targets=JsonMap.Child(data,"targets");foreach(var g in Groups(d)){var ids=JsonMap.Items(g,"ids").Select(Convert.ToString).ToArray();var found=ids.Select(id=>S(links,id)).Where(k=>targets.ContainsKey(k)&&Compatible(g,JsonMap.Child(targets,k))).Distinct().ToArray();if(found.Length==0){var candidates=new HashSet<string>();foreach(var source in sources){var prior=Read(source);if(prior==null)continue;var refs=JsonMap.Child(prior,"links");foreach(var old in Groups(source).Where(x=>Compatible(g,x)&&N(x,"start")<N(g,"end")&&N(x,"end")>N(g,"start")))foreach(string id in JsonMap.Items(old,"ids").Select(Convert.ToString)){string key=S(refs,id);if(targets.ContainsKey(key)&&Compatible(g,JsonMap.Child(targets,key)))candidates.Add(key);}}found=candidates.ToArray();}if(found.Length==1)foreach(string id in ids)links[id]=found[0];}data["links"]=links;d.AdherenceState=JsonMap.Write(data);}
 public static string Merge(string b,string l,string c,bool force){if(l==b)return c;if(c==b||l==c||force)return l;var baseline=string.IsNullOrEmpty(b)?JsonMap.Obj():JsonMap.Read(b);var local=string.IsNullOrEmpty(l)?JsonMap.Obj():JsonMap.Read(l);var current=string.IsNullOrEmpty(c)?JsonMap.Obj():JsonMap.Read(c);var result=JsonMap.Obj();foreach(string field in new[]{"version","initial","initial_known"}){object old=baseline.ContainsKey(field)?baseline[field]:null,a=local.ContainsKey(field)?local[field]:null,z=current.ContainsKey(field)?current[field]:null;if(JsonMap.Write(a)==JsonMap.Write(old))result[field]=z;else if(JsonMap.Write(z)==JsonMap.Write(old)||JsonMap.Write(z)==JsonMap.Write(a))result[field]=a;else throw new SyncConflict("양쪽의 이행도 최초 계획이 다릅니다. 기록을 보관하고 사용할 내용을 선택해 주세요.");}foreach(string field in new[]{"links","targets"}){var old=JsonMap.Child(baseline,field);var mine=JsonMap.Child(local,field);var remote=JsonMap.Child(current,field);var dest=JsonMap.Obj();foreach(string k in old.Keys.Concat(mine.Keys).Concat(remote.Keys).Distinct()){object x=old.ContainsKey(k)?old[k]:null,a=mine.ContainsKey(k)?mine[k]:null,z=remote.ContainsKey(k)?remote[k]:null;if(JsonMap.Write(a)==JsonMap.Write(x))dest[k]=z;else if(JsonMap.Write(z)==JsonMap.Write(x)||JsonMap.Write(z)==JsonMap.Write(a))dest[k]=a;else throw new SyncConflict("같은 행동의 이행도 기준을 양쪽에서 수정했습니다.");}result[field]=dest;}result["legacy_ids"]=JsonMap.Items(local,"legacy_ids").Concat(JsonMap.Items(current,"legacy_ids")).Select(Convert.ToString).Distinct().ToArray();result["revisions"]=JsonMap.Items(local,"revisions").Concat(JsonMap.Items(current,"revisions")).Select(JsonMap.Map).GroupBy(x=>S(x,"id")).Select(g=>g.First()).OrderBy(x=>S(x,"at")).ToArray();return JsonMap.Write(result);}
}}
